//! The classic-BPF seccomp filter, built by hand.
//!
//! Written out rather than generated by `seccompiler` or `libseccomp` on purpose. The
//! filter is a few dozen fixed instructions and it is the thing standing between cargo
//! and a third party's code; a reviewer who does not trust buildclamp has to be able to
//! read it, and a dependency that generates it moves the thing being audited out of the
//! repository.
//!
//! # The architecture gate comes first, and kills
//!
//! A seccomp filter matches on syscall *numbers*, and those numbers mean different things
//! on different architectures. A filter that checked `SYS_connect` without first pinning
//! the architecture would, under a 32-bit compat call, be testing an unrelated syscall —
//! which is the classic seccomp bypass. So the first instructions check
//! `seccomp_data.arch` and kill on anything else, and on x86-64 they also kill the x32
//! ABI, which reports the same `arch` but renumbers syscalls with bit `0x40000000` set.
//!
//! # A syscall filter has to refuse the ring
//!
//! Every check below matches a syscall number, and `io_uring` exists to perform work
//! without issuing the syscall that names it. A unit that can call `io_uring_setup` can
//! open, connect and send through queue entries the filter never sees. So the three ring
//! syscalls return `EPERM` unconditionally, in every mode, with no policy knob — the same
//! treatment as `ptrace`, and for the same reason: they are a way out of everything else
//! here.
//!
//! # Write-open filtering happens in the kernel
//!
//! Read-only `open`s are not notified. The filter tests the open flags in BPF and only
//! notifies when one of `O_WRONLY`, `O_RDWR`, `O_CREAT` or `O_TRUNC` is set. Measured:
//! 2,000 read-only opens produce **zero** notifications, against 10–40 µs each if they
//! did. rustc opens thousands of files per compile, so this is the difference between a
//! tool people keep and one they remove.

use libc::sock_filter;

/// `AUDIT_ARCH_X86_64` from `<linux/audit.h>`. Not exported by libc 0.2.
pub const AUDIT_ARCH_X86_64: u32 = 0xc000_003e;
/// `AUDIT_ARCH_AARCH64`. Also not exported by libc 0.2.
pub const AUDIT_ARCH_AARCH64: u32 = 0xc000_00b7;

/// x32 syscalls report `arch == AUDIT_ARCH_X86_64` but carry this bit in the number, so
/// every number check below would be testing the wrong syscall. Killed explicitly.
const X32_SYSCALL_BIT: u32 = 0x4000_0000;

// `struct seccomp_data` offsets. Little-endian, so the low 32 bits of `args[i]` sit at
// the argument's own offset — which is all the flag tests need.
const OFF_NR: u32 = 0;
const OFF_ARCH: u32 = 4;
const fn off_arg_lo(i: u32) -> u32 {
    16 + 8 * i
}

/// An `open` is write-class if any of these flag bits is set.
pub const WRITE_OPEN_MASK: u32 =
    (libc::O_WRONLY | libc::O_RDWR | libc::O_CREAT | libc::O_TRUNC) as u32;

/// The architecture this filter is being built for.
///
/// A filter is only valid for the architecture it was built for, so this is a compile-time
/// fact rather than a runtime choice — but it is a parameter so the tables can be tested
/// for both on either.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Arch {
    X86_64,
    Aarch64,
}

impl Arch {
    /// The architecture this binary was compiled for.
    pub const NATIVE: Arch = if cfg!(target_arch = "aarch64") {
        Arch::Aarch64
    } else {
        Arch::X86_64
    };

    pub fn audit(self) -> u32 {
        match self {
            Arch::X86_64 => AUDIT_ARCH_X86_64,
            Arch::Aarch64 => AUDIT_ARCH_AARCH64,
        }
    }
}

/// Syscall numbers this filter cares about, per architecture.
///
/// **`None` means the architecture does not have that syscall**, and the entry is simply
/// omitted from the filter. aarch64 is a "new" architecture: it has only the `*at` forms,
/// with no `open`, `mkdir`, `unlink`, `rename`, `symlink`, `link`, `rmdir` or `chmod`.
/// Emitting a wrong number for a missing syscall would filter something unrelated, which
/// is exactly the class of bug the architecture gate exists to prevent.
#[derive(Clone, Copy, Debug)]
pub struct Syscalls {
    socket: Option<i64>,
    connect: Option<i64>,
    /// The datagram senders. Kept in the table but **deliberately never put in the
    /// filter** — notifying on `sendmsg` deadlocks the listener handover. See the comment
    /// in [`build`], and the test that stops anyone adding them back.
    #[cfg_attr(not(test), allow(dead_code))]
    sendto: Option<i64>,
    #[cfg_attr(not(test), allow(dead_code))]
    sendmsg: Option<i64>,
    #[cfg_attr(not(test), allow(dead_code))]
    sendmmsg: Option<i64>,
    execve: Option<i64>,
    execveat: Option<i64>,
    open: Option<i64>,
    openat: Option<i64>,
    openat2: Option<i64>,
    creat: Option<i64>,
    mkdir: Option<i64>,
    mkdirat: Option<i64>,
    unlink: Option<i64>,
    unlinkat: Option<i64>,
    rmdir: Option<i64>,
    rename: Option<i64>,
    renameat: Option<i64>,
    renameat2: Option<i64>,
    symlink: Option<i64>,
    symlinkat: Option<i64>,
    link: Option<i64>,
    linkat: Option<i64>,
    truncate: Option<i64>,
    chmod: Option<i64>,
    fchmodat: Option<i64>,
    ptrace: Option<i64>,
    process_vm_readv: Option<i64>,
    process_vm_writev: Option<i64>,
    /// The ring. Denied outright — see the note in [`build`].
    ///
    /// Same numbers on both architectures: `io_uring` arrived after x86-64 and the
    /// asm-generic table had converged, so 425/426/427 mean the same thing on each.
    io_uring_setup: Option<i64>,
    io_uring_enter: Option<i64>,
    io_uring_register: Option<i64>,
}

/// x86-64 numbers, from `arch/x86/entry/syscalls/syscall_64.tbl`.
const X86_64: Syscalls = Syscalls {
    socket: Some(41),
    connect: Some(42),
    sendto: Some(44),
    sendmsg: Some(46),
    sendmmsg: Some(307),
    execve: Some(59),
    execveat: Some(322),
    open: Some(2),
    openat: Some(257),
    openat2: Some(437),
    creat: Some(85),
    mkdir: Some(83),
    mkdirat: Some(258),
    unlink: Some(87),
    unlinkat: Some(263),
    rmdir: Some(84),
    rename: Some(82),
    renameat: Some(264),
    renameat2: Some(316),
    symlink: Some(88),
    symlinkat: Some(266),
    link: Some(86),
    linkat: Some(265),
    truncate: Some(76),
    chmod: Some(90),
    fchmodat: Some(268),
    ptrace: Some(101),
    process_vm_readv: Some(310),
    process_vm_writev: Some(311),
    io_uring_setup: Some(425),
    io_uring_enter: Some(426),
    io_uring_register: Some(427),
};

/// aarch64 numbers, from the asm-generic table. Note the many `None`s: this architecture
/// never had the non-`at` forms.
const AARCH64: Syscalls = Syscalls {
    socket: Some(198),
    connect: Some(203),
    sendto: Some(206),
    sendmsg: Some(211),
    sendmmsg: Some(269),
    execve: Some(221),
    execveat: Some(281),
    open: None,
    openat: Some(56),
    openat2: Some(437),
    creat: None,
    mkdir: None,
    mkdirat: Some(34),
    unlink: None,
    unlinkat: Some(35),
    rmdir: None,
    rename: None,
    renameat: None,
    renameat2: Some(276),
    symlink: None,
    symlinkat: Some(36),
    link: None,
    linkat: Some(37),
    truncate: Some(45),
    chmod: None,
    fchmodat: Some(53),
    ptrace: Some(117),
    process_vm_readv: Some(270),
    process_vm_writev: Some(271),
    io_uring_setup: Some(425),
    io_uring_enter: Some(426),
    io_uring_register: Some(427),
};

fn table(arch: Arch) -> Syscalls {
    match arch {
        Arch::X86_64 => X86_64,
        Arch::Aarch64 => AARCH64,
    }
}

/// The table for an architecture, for the reference interpreter's oracle.
///
/// Public so that [`crate::linux::bpfcheck`] can state what the filter *should* answer
/// from the same numbers the builder compares against. Sharing the numbers is deliberate:
/// the differential is about the program's **encoding** — offsets, ordering, the
/// architecture gate, flag masks — and a second copy of the syscall numbers would test
/// nothing but transcription, while making every number twice as expensive to correct.
pub fn table_for(arch: Arch) -> Syscalls {
    table(arch)
}

/// The categories, as a second statement of the filter's intent.
///
/// Each of these lists the same fields [`build`] reaches for, written out separately and
/// on purpose. A syscall added to one and not the other is a disagreement the differential
/// finds on the next run — which is what makes forgetting to update one of them a failing
/// test rather than a hole in a filter.
impl Syscalls {
    /// Refused outright, with no notification and no policy knob.
    pub fn denied(&self) -> Vec<i64> {
        [
            self.ptrace,
            self.process_vm_readv,
            self.process_vm_writev,
            self.io_uring_setup,
            self.io_uring_enter,
            self.io_uring_register,
        ]
        .into_iter()
        .flatten()
        .collect()
    }

    /// Notified when `observe_net` is on, so a destination can be recorded.
    pub fn net_observed(&self) -> Vec<i64> {
        [self.socket, self.connect].into_iter().flatten().collect()
    }

    /// Notified always: exec is recorded on every unit whether or not it is granted.
    pub fn exec_observed(&self) -> Vec<i64> {
        [self.execve, self.execveat].into_iter().flatten().collect()
    }

    /// Notified unconditionally when `observe_writes` is on. Does **not** include the two
    /// flag-tested opens, which are [`Syscalls::open_flag_argument`]'s, nor `openat2`,
    /// which is [`Syscalls::openat2_number`]'s.
    pub fn write_observed(&self) -> Vec<i64> {
        [
            self.creat,
            self.mkdir,
            self.mkdirat,
            self.unlink,
            self.unlinkat,
            self.rmdir,
            self.rename,
            self.renameat,
            self.renameat2,
            self.symlink,
            self.symlinkat,
            self.link,
            self.linkat,
            self.truncate,
            self.chmod,
            self.fchmodat,
        ]
        .into_iter()
        .flatten()
        .collect()
    }

    /// Which argument slot carries this syscall's open flags, for the two opens whose
    /// flags BPF can read at all.
    ///
    /// `open(path, flags, …)` is slot 1 and `openat(dirfd, path, flags, …)` is slot 2.
    /// Getting this wrong judges every write-open on a path pointer, whose low bits are
    /// arbitrary — so the verdict is right about half the time and the bug survives any
    /// test that puts the same value in every slot.
    pub fn open_flag_argument(&self, nr: i64) -> Option<usize> {
        if self.open == Some(nr) {
            Some(1)
        } else if self.openat == Some(nr) {
            Some(2)
        } else {
            None
        }
    }

    /// `openat2`, which is notified unconditionally because its flags live in a struct in
    /// the caller's memory where no BPF test can reach them.
    pub fn openat2_number(&self) -> Option<i64> {
        self.openat2
    }

    /// Every number this table names, for a sweep that wants to cover the boundaries.
    pub fn every_number(&self) -> Vec<i64> {
        let mut out: Vec<i64> = self
            .denied()
            .into_iter()
            .chain(self.net_observed())
            .chain(self.exec_observed())
            .chain(self.write_observed())
            .chain(self.openat2_number())
            .chain(self.open)
            .chain(self.openat)
            .chain(self.sendto)
            .chain(self.sendmsg)
            .chain(self.sendmmsg)
            .collect();
        out.sort_unstable();
        out.dedup();
        out
    }
}

/// What the filter should do.
#[derive(Clone, Copy, Debug, Default)]
pub struct FilterOptions {
    /// Notify on write-class file operations. Off for compile units under a
    /// kernel-enforced filesystem tier, where rustc's thousands of opens would dominate
    /// the build's cost for nothing.
    pub observe_writes: bool,
    /// Notify on `socket` and `connect` so destinations can be recorded.
    ///
    /// Even when the network is already denied by an empty namespace: the namespace makes
    /// the connection fail, and the notification is what lets the report say *where* it
    /// was going. That destination is the single most useful line in an incident.
    pub observe_net: bool,
    /// The architecture to build for.
    pub arch: Arch,
}

impl FilterOptions {
    pub fn for_native() -> Self {
        Self {
            arch: Arch::NATIVE,
            ..Default::default()
        }
    }
}

impl Default for Arch {
    fn default() -> Self {
        Arch::NATIVE
    }
}

/// Build the filter.
pub fn build(opts: &FilterOptions) -> Result<Vec<sock_filter>, String> {
    let sys = table(opts.arch);
    let mut b = Builder::new();
    let notify = b.label();
    let allow = b.label();
    let eperm = b.label();
    let kill = b.label();
    let open_flags_arg1 = b.label();
    let open_flags_arg2 = b.label();
    let openat2_notify = b.label();

    // The architecture gate, first, before any syscall number is compared. Without it a
    // 32-bit compat call would be matched against this architecture's numbering.
    b.ld_abs_w(OFF_ARCH);
    b.jne(opts.arch.audit(), kill);
    b.ld_abs_w(OFF_NR);
    if opts.arch == Arch::X86_64 {
        b.jset_to(X32_SYSCALL_BIT, kill);
    }

    if opts.observe_net {
        // `socket` carries the address family and `connect` carries the destination.
        //
        // The datagram senders — `sendto`, `sendmsg`, `sendmmsg` — are deliberately NOT
        // here, and the reason is a deadlock that cost an afternoon. The listener
        // descriptor this filter creates has to be handed from the child to the parent,
        // and the only way to move a descriptor between processes is `sendmsg` with
        // `SCM_RIGHTS`. Notify on `sendmsg` and the child traps on the very call that
        // carries the listener, while the parent blocks waiting for the listener that
        // call was carrying. Neither can proceed. It is a clean bootstrapping deadlock
        // and no ordering fixes it, because the filter must exist before the descriptor
        // it produces can be sent.
        //
        // What is lost is smaller than it looks. Denial is unaffected: `socket` is
        // notified, so an `AF_INET` socket is refused before any datagram can be sent,
        // and you cannot `sendto` without a socket. What is lost is *recording* the
        // destination of a UDP send that never calls `connect` — a DNS query, for
        // instance — while in observe mode, where nothing is denied. Such a send shows up
        // as a socket creation with no destination. `crates/sandbox/README` and the
        // module docs say so rather than leaving it to be discovered.
        for nr in [sys.socket, sys.connect].into_iter().flatten() {
            b.jeq(nr as u32, notify);
        }
    }

    // `execve` is always notified: exec is recorded on every unit, whether or not the
    // policy grants it, so a build script that spawns something surprising is visible
    // even when nothing refused it.
    for nr in [sys.execve, sys.execveat].into_iter().flatten() {
        b.jeq(nr as u32, notify);
    }

    if opts.observe_writes {
        // Flag-tested, so read-only opens never reach the supervisor.
        if let Some(nr) = sys.openat {
            b.jeq(nr as u32, open_flags_arg2);
        }
        if let Some(nr) = sys.open {
            b.jeq(nr as u32, open_flags_arg1);
        }
        // `openat2` puts its flags in a `struct open_how` in the caller's memory rather
        // than in a register, so BPF cannot test them. Notify unconditionally and let the
        // supervisor read the struct; missing it entirely would leave an open hole,
        // since it is a complete replacement for `openat`.
        if let Some(nr) = sys.openat2 {
            b.jeq(nr as u32, openat2_notify);
        }
        for nr in [
            sys.creat,
            sys.mkdir,
            sys.mkdirat,
            sys.unlink,
            sys.unlinkat,
            sys.rmdir,
            sys.rename,
            sys.renameat,
            sys.renameat2,
            sys.symlink,
            sys.symlinkat,
            sys.link,
            sys.linkat,
            sys.truncate,
            sys.chmod,
            sys.fchmodat,
        ]
        .into_iter()
        .flatten()
        {
            b.jeq(nr as u32, notify);
        }
    }

    // Denied outright, with no notification and no policy knob. A build script has no
    // legitimate reason to attach a debugger to another process or read its memory, and
    // both are ways out of everything else this filter does — a unit that could
    // `process_vm_writev` into the supervisor would own the sandbox.
    //
    // `io_uring` is here for the same reason and it is the more important one. Every
    // check above matches on a syscall number, and a ring performs the operation
    // *without issuing that syscall*: `IORING_OP_OPENAT`, `IORING_OP_CONNECT` and
    // `IORING_OP_SENDMSG` are submitted as entries in a shared queue and executed by
    // kernel workers, so a unit holding a ring opens files and reaches the network with
    // the filter above never matching once. Notification cannot help — there is no
    // syscall to notify on — so the ring itself has to be refused at the door, which is
    // why the setup call is denied rather than the submissions. This is not specific to
    // buildclamp; it is why the default docker profile and gVisor block these three too.
    for nr in [
        sys.ptrace,
        sys.process_vm_readv,
        sys.process_vm_writev,
        sys.io_uring_setup,
        sys.io_uring_enter,
        sys.io_uring_register,
    ]
    .into_iter()
    .flatten()
    {
        b.jeq(nr as u32, eperm);
    }

    b.ret(libc::SECCOMP_RET_ALLOW);

    if opts.observe_writes {
        b.bind(open_flags_arg2); // openat(dirfd, path, flags, …) — flags is arg 2
        b.ld_abs_w(off_arg_lo(2));
        b.jset(WRITE_OPEN_MASK, notify, allow);
        b.bind(open_flags_arg1); // open(path, flags, …) — flags is arg 1
        b.ld_abs_w(off_arg_lo(1));
        b.jset(WRITE_OPEN_MASK, notify, allow);
        b.bind(openat2_notify);
        b.ret(libc::SECCOMP_RET_USER_NOTIF);
    }

    b.bind(notify);
    b.ret(libc::SECCOMP_RET_USER_NOTIF);
    b.bind(allow);
    b.ret(libc::SECCOMP_RET_ALLOW);
    b.bind(eperm);
    b.ret(libc::SECCOMP_RET_ERRNO | (libc::EPERM as u32 & 0xffff));
    b.bind(kill);
    b.ret(libc::SECCOMP_RET_KILL_PROCESS);
    b.finish()
}

// --- the builder ------------------------------------------------------------------

/// A forward jump target, resolved by [`Builder::finish`].
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Label(usize);

#[derive(Clone, Copy)]
enum Slot {
    Jt,
    Jf,
}

/// A tiny label-based assembler for classic BPF.
///
/// Classic BPF jump offsets are unsigned bytes relative to the *next* instruction, so
/// only forward jumps exist and only for 255 instructions. Writing those offsets by hand
/// is how filters get subtly wrong, so they are computed here and a jump that cannot be
/// encoded is an error rather than a truncation.
#[derive(Default, Debug)]
pub struct Builder {
    insns: Vec<sock_filter>,
    labels: Vec<Option<usize>>,
    fixups: Vec<(usize, Slot, Label)>,
}

impl std::fmt::Debug for Slot {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(match self {
            Slot::Jt => "jt",
            Slot::Jf => "jf",
        })
    }
}

fn insn(code: u32, k: u32) -> sock_filter {
    sock_filter {
        code: code as u16,
        jt: 0,
        jf: 0,
        k,
    }
}

impl Builder {
    pub fn new() -> Self {
        Self::default()
    }

    pub fn label(&mut self) -> Label {
        self.labels.push(None);
        Label(self.labels.len() - 1)
    }

    pub fn bind(&mut self, l: Label) {
        assert!(self.labels[l.0].is_none(), "label bound twice");
        self.labels[l.0] = Some(self.insns.len());
    }

    /// `A = *(u32 *)(seccomp_data + off)`
    pub fn ld_abs_w(&mut self, off: u32) {
        self.insns
            .push(insn(libc::BPF_LD | libc::BPF_W | libc::BPF_ABS, off));
    }

    fn jump(&mut self, cond: u32, k: u32, jt: Option<Label>, jf: Option<Label>) {
        let idx = self.insns.len();
        self.insns.push(insn(libc::BPF_JMP | cond | libc::BPF_K, k));
        if let Some(l) = jt {
            self.fixups.push((idx, Slot::Jt, l));
        }
        if let Some(l) = jf {
            self.fixups.push((idx, Slot::Jf, l));
        }
    }

    /// `if A == k goto jt` else fall through.
    pub fn jeq(&mut self, k: u32, jt: Label) {
        self.jump(libc::BPF_JEQ, k, Some(jt), None)
    }

    /// `if A != k goto jf` else fall through.
    pub fn jne(&mut self, k: u32, jf: Label) {
        self.jump(libc::BPF_JEQ, k, None, Some(jf))
    }

    /// `if (A & k) != 0 goto jt else goto jf`.
    pub fn jset(&mut self, k: u32, jt: Label, jf: Label) {
        self.jump(libc::BPF_JSET, k, Some(jt), Some(jf))
    }

    /// `if (A & k) != 0 goto jt` else fall through.
    pub fn jset_to(&mut self, k: u32, jt: Label) {
        self.jump(libc::BPF_JSET, k, Some(jt), None)
    }

    pub fn ret(&mut self, k: u32) {
        self.insns.push(insn(libc::BPF_RET | libc::BPF_K, k));
    }

    /// Resolve every label into a forward offset.
    ///
    /// Refuses rather than truncating: a backward jump or one beyond 255 instructions
    /// would silently produce a filter that does something other than what was written,
    /// and a wrong seccomp filter fails open.
    pub fn finish(mut self) -> Result<Vec<sock_filter>, String> {
        let fixups = std::mem::take(&mut self.fixups);
        for (idx, slot, l) in fixups {
            let target = self.labels[l.0]
                .ok_or_else(|| format!("label {l:?} was referenced but never bound"))?;
            if target <= idx {
                return Err(format!("backward jump at instruction {idx} to {target}"));
            }
            let delta = target - (idx + 1);
            if delta > u8::MAX as usize {
                return Err(format!(
                    "jump at instruction {idx} is {delta} away, beyond BPF's 255 limit"
                ));
            }
            match slot {
                Slot::Jt => self.insns[idx].jt = delta as u8,
                Slot::Jf => self.insns[idx].jf = delta as u8,
            }
        }
        if self.insns.len() > u16::MAX as usize {
            return Err("filter is too long for the kernel's limit".into());
        }
        Ok(self.insns)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn opts(arch: Arch, writes: bool, net: bool) -> FilterOptions {
        FilterOptions {
            observe_writes: writes,
            observe_net: net,
            arch,
        }
    }

    #[test]
    fn a_filter_builds_for_both_architectures_in_every_mode() {
        // The aarch64 table has many missing syscalls, so its filter is a different shape.
        // Building it on an x86 host is the only way that table is ever exercised.
        for arch in [Arch::X86_64, Arch::Aarch64] {
            for (w, n) in [(false, false), (true, false), (false, true), (true, true)] {
                let f =
                    build(&opts(arch, w, n)).unwrap_or_else(|e| panic!("{arch:?} {w} {n}: {e}"));
                assert!(!f.is_empty());
                assert!(f.len() < 256, "{arch:?}: filter grew past the jump limit");
            }
        }
    }

    #[test]
    fn the_architecture_gate_is_the_first_thing_the_filter_does() {
        // A number comparison before the arch check would be testing an unrelated syscall
        // under a compat call. This is the classic seccomp bypass.
        let f = build(&opts(Arch::X86_64, true, true)).unwrap();
        assert_eq!(
            f[0].code,
            (libc::BPF_LD | libc::BPF_W | libc::BPF_ABS) as u16
        );
        assert_eq!(f[0].k, OFF_ARCH);
        assert_eq!(
            f[1].code,
            (libc::BPF_JMP | libc::BPF_JEQ | libc::BPF_K) as u16
        );
        assert_eq!(f[1].k, AUDIT_ARCH_X86_64);
    }

    #[test]
    fn x86_64_kills_the_x32_abi_and_aarch64_has_no_such_check() {
        let x86 = build(&opts(Arch::X86_64, false, false)).unwrap();
        assert!(
            x86.iter().any(|i| i.k == X32_SYSCALL_BIT),
            "the x32 numbering bypass is not closed"
        );
        let arm = build(&opts(Arch::Aarch64, false, false)).unwrap();
        assert!(
            !arm.iter().any(|i| i.k == X32_SYSCALL_BIT),
            "aarch64 has no x32 ABI; checking for it would be noise"
        );
    }

    #[test]
    fn a_syscall_absent_on_an_architecture_is_omitted_rather_than_given_a_wrong_number() {
        // aarch64 has no `open`, `mkdir`, `unlink`, `rename` or `chmod`. Emitting x86's
        // numbers for them would filter unrelated syscalls — the exact bug the
        // architecture gate exists to prevent, reintroduced one level down.
        let arm = build(&opts(Arch::Aarch64, true, true)).unwrap();
        for absent in [
            X86_64.open.unwrap(),
            X86_64.mkdir.unwrap(),
            X86_64.unlink.unwrap(),
            X86_64.rename.unwrap(),
            X86_64.chmod.unwrap(),
        ] {
            // Those x86 numbers are real aarch64 syscalls (2 = something else entirely),
            // so the only safe assertion is that we never compare against them as if they
            // were the operations they name on x86.
            let count = arm.iter().filter(|i| i.k == absent as u32).count();
            assert_eq!(
                count, 0,
                "aarch64 filter references x86 syscall number {absent}"
            );
        }
        assert!(AARCH64.open.is_none());
        assert!(AARCH64.chmod.is_none());
    }

    #[test]
    fn write_open_filtering_tests_the_flags_argument_at_the_right_offset() {
        // openat's flags are argument 2; open's are argument 1. Getting these the wrong
        // way round would notify on every read and miss every write.
        let f = build(&opts(Arch::X86_64, true, false)).unwrap();
        assert!(f.iter().any(|i| i.k == off_arg_lo(2)));
        assert!(f.iter().any(|i| i.k == off_arg_lo(1)));
        assert!(f.iter().any(|i| i.k == WRITE_OPEN_MASK));
    }

    #[test]
    fn without_write_observation_no_open_appears_in_the_filter_at_all() {
        // The performance claim: rustc's thousands of read-only opens must not reach the
        // supervisor, and the cheapest way to guarantee that is for them not to be in the
        // filter.
        let f = build(&opts(Arch::X86_64, false, true)).unwrap();
        assert!(!f.iter().any(|i| i.k == X86_64.openat.unwrap() as u32));
        assert!(!f.iter().any(|i| i.k == WRITE_OPEN_MASK));
    }

    #[test]
    fn the_datagram_senders_are_deliberately_absent_or_the_handover_deadlocks() {
        // Notifying on `sendmsg` traps the very call that hands the listener descriptor
        // from the child to the parent, while the parent blocks waiting for it. This test
        // is here so nobody adds them back for the (real, and smaller) DNS-recording
        // benefit without hitting the deadlock first.
        let f = build(&opts(Arch::X86_64, true, true)).unwrap();
        for nr in [X86_64.sendto, X86_64.sendmsg, X86_64.sendmmsg] {
            assert!(
                !f.iter().any(|i| i.k == nr.unwrap() as u32),
                "syscall {nr:?} is in the filter; the listener handover will deadlock"
            );
        }
        // Denial is unaffected: refusing `socket` means there is nothing to send from.
        assert!(f.iter().any(|i| i.k == X86_64.socket.unwrap() as u32));
        assert!(f.iter().any(|i| i.k == X86_64.connect.unwrap() as u32));
    }

    #[test]
    fn ptrace_and_cross_process_memory_are_denied_in_every_mode() {
        // A unit that could write into the supervisor's memory would own the sandbox.
        // There is deliberately no policy knob for this.
        for (w, n) in [(false, false), (true, true)] {
            let f = build(&opts(Arch::X86_64, w, n)).unwrap();
            for nr in [
                X86_64.ptrace,
                X86_64.process_vm_readv,
                X86_64.process_vm_writev,
            ] {
                assert!(
                    f.iter().any(|i| i.k == nr.unwrap() as u32),
                    "missing {nr:?}"
                );
            }
            assert!(f
                .iter()
                .any(|i| i.k == libc::SECCOMP_RET_ERRNO | libc::EPERM as u32));
        }
    }

    #[test]
    fn the_ring_is_refused_on_both_architectures_and_in_every_mode() {
        // The bypass this closes: `io_uring_enter` submits `IORING_OP_OPENAT` and
        // `IORING_OP_CONNECT` as queue entries, so a unit holding a ring opens files and
        // reaches the network without ever issuing a syscall any check above matches.
        // Notification is no help — there is no syscall to notify on — so the refusal has
        // to be of the ring itself, unconditionally.
        for arch in [Arch::X86_64, Arch::Aarch64] {
            let t = table(arch);
            for (w, n) in [(false, false), (false, true), (true, false), (true, true)] {
                let f = build(&opts(arch, w, n)).unwrap();
                for nr in [t.io_uring_setup, t.io_uring_enter, t.io_uring_register] {
                    let nr = nr.expect("every supported architecture has io_uring");
                    let pos = f
                        .iter()
                        .position(|i| i.k == nr as u32)
                        .unwrap_or_else(|| panic!("{arch:?} writes={w} net={n}: {nr} absent"));
                    // Not merely present: it must not be reachable only through the
                    // observe_writes branch, which is off for compile units.
                    assert!(pos > 1, "the architecture gate must still come first");
                }
                assert!(f
                    .iter()
                    .any(|i| i.k == libc::SECCOMP_RET_ERRNO | libc::EPERM as u32));
            }
        }
    }

    #[test]
    fn the_ring_numbers_are_the_same_on_both_architectures() {
        // io_uring landed after the asm-generic table had converged with x86-64, so these
        // three are the rare case where one number is right everywhere. Asserted rather
        // than assumed, because a copied-down table is how a filter comes to guard an
        // unrelated syscall.
        assert_eq!(X86_64.io_uring_setup, Some(425));
        assert_eq!(X86_64.io_uring_enter, Some(426));
        assert_eq!(X86_64.io_uring_register, Some(427));
        assert_eq!(AARCH64.io_uring_setup, X86_64.io_uring_setup);
        assert_eq!(AARCH64.io_uring_enter, X86_64.io_uring_enter);
        assert_eq!(AARCH64.io_uring_register, X86_64.io_uring_register);
    }

    #[test]
    fn openat2_is_notified_unconditionally_because_bpf_cannot_read_its_flags() {
        // openat2 puts its flags in a struct in the caller's memory. Missing it would
        // leave a complete replacement for openat unfiltered.
        let f = build(&opts(Arch::X86_64, true, false)).unwrap();
        assert!(f.iter().any(|i| i.k == X86_64.openat2.unwrap() as u32));
    }

    #[test]
    fn a_jump_that_cannot_be_encoded_is_an_error_rather_than_a_truncation() {
        // A wrong seccomp filter fails open, so a silently truncated offset would be a
        // sandbox that does nothing while looking installed.
        let mut b = Builder::new();
        let far = b.label();
        b.jeq(1, far);
        for _ in 0..300 {
            b.ret(libc::SECCOMP_RET_ALLOW);
        }
        b.bind(far);
        b.ret(libc::SECCOMP_RET_ALLOW);
        let err = b.finish().unwrap_err();
        assert!(err.contains("beyond BPF's 255 limit"), "{err}");
    }

    #[test]
    fn a_label_that_is_never_bound_is_an_error() {
        let mut b = Builder::new();
        let dangling = b.label();
        b.jeq(1, dangling);
        b.ret(libc::SECCOMP_RET_ALLOW);
        assert!(b.finish().unwrap_err().contains("never bound"));
    }
}
